package local.tvmorph.tv;
import java.net.*;import java.io.*;import java.util.*;import org.json.*;
/** Solicited M-SEARCH only; no subnet scans or unsolicited NOTIFY fetches. */
final class LanSsdp {
 volatile DatagramSocket socket;volatile boolean cancelled;
 static JSONObject parse(String message,InetAddress sender)throws Exception{if(message.length()>8192||!message.startsWith("HTTP/1.1 200")||!LanPolicy.local(sender))return null;Map<String,String> h=new HashMap<>();for(String line:message.split("\r?\n")){int n=line.indexOf(':');if(n>0){String key=line.substring(0,n).trim().toLowerCase(Locale.ROOT);if(h.containsKey(key))return null;h.put(key,line.substring(n+1).trim());}}String location=h.get("location");if(location==null)return null;URI u=LanPolicy.validate(location);boolean matches=false;for(InetAddress a:InetAddress.getAllByName(u.getHost()))if(a.equals(sender))matches=true;if(!matches)return null;String type=h.getOrDefault("st","");if(!type.contains("MediaServer")&&!type.equals("upnp:rootdevice"))return null;return new JSONObject().put("id",h.getOrDefault("usn",location).split("::")[0]).put("url",location).put("name",sender.getHostAddress()).put("type","discovered").put("status","Discovered; select to inspect");}
   JSONArray scan()throws Exception{LinkedHashMap<String,JSONObject> rows=new LinkedHashMap<>();HashSet<String> locations=new HashSet<>();try{if(cancelled)throw new IOException("Cancelled.");MulticastSocket multicast=new MulticastSocket(0);multicast.setTimeToLive(1);socket=multicast;socket.setSoTimeout(250);
   java.util.List<InetAddress> locals=new java.util.ArrayList<>();
   try{Enumeration<NetworkInterface> nis=NetworkInterface.getNetworkInterfaces();while(nis!=null&&nis.hasMoreElements()){NetworkInterface ni=nis.nextElement();try{if(!ni.isUp()||ni.isLoopback()||!ni.supportsMulticast())continue;}catch(Exception skip){continue;}Enumeration<InetAddress> addrs=ni.getInetAddresses();while(addrs.hasMoreElements()){InetAddress a=addrs.nextElement();if(a instanceof Inet4Address&&LanPolicy.local(a)&&!locals.contains(a))locals.add(a);}}}catch(Exception ignored){}
   String[] targets={"urn:schemas-upnp-org:device:MediaServer:1","urn:schemas-upnp-org:device:MediaServer:2","upnp:rootdevice"};for(InetAddress local:locals){try{multicast.setInterface(local);}catch(Exception ignored){}for(String target:targets){if(cancelled)throw new IOException("Cancelled.");String msg="M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\nMAN: \"ssdp:discover\"\r\nMX: 2\r\nST: "+target+"\r\n\r\n";byte[] data=msg.getBytes("US-ASCII");socket.send(new DatagramPacket(data,data.length,InetAddress.getByName("239.255.255.250"),1900));}}
   if(locals.isEmpty())for(String target:targets){String msg="M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\nMAN: \"ssdp:discover\"\r\nMX: 2\r\nST: "+target+"\r\n\r\n";byte[] data=msg.getBytes("US-ASCII");socket.send(new DatagramPacket(data,data.length,InetAddress.getByName("239.255.255.250"),1900));}long end=System.nanoTime()+6000000000L;while(!cancelled&&System.nanoTime()<end&&rows.size()<32){byte[] bytes=new byte[8192];DatagramPacket packet=new DatagramPacket(bytes,bytes.length);try{socket.receive(packet);JSONObject row=parse(new String(packet.getData(),0,packet.getLength(),"UTF-8"),packet.getAddress());if(row!=null&&!locations.contains(row.getString("url"))&&!rows.containsKey(row.getString("id"))){rows.put(row.getString("id"),row);locations.add(row.getString("url"));}}catch(SocketTimeoutException ignored){}catch(Exception bad){if(cancelled)break;}}}finally{cancel();}JSONArray out=new JSONArray();for(JSONObject row:rows.values())out.put(row);return out;}
 void cancel(){cancelled=true;DatagramSocket s=socket;if(s!=null)s.close();socket=null;}
}
